def _streamed_cue(text, question=''):
    from echo_sync.first_useful import first_cue
    for k in range(1, len(text) + 1):
        cue = first_cue(text[:k], question, SENSE, final=k == len(text), last=k == len(text))
        if cue:
            return cue


